{"command":"cat << 'EOF' > src/cli.rs
use clap::{builder::ValueParser, Arg, ArgAction, Command};
use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct Opts {
    pub paths: Vec<PathBuf>,
    pub verbose: u8,
    pub recursive: bool,
    pub dereference: bool,
    pub workers: usize,
    pub block_size: u64,
    pub no_clobber: bool,
    pub force: bool,
    pub gitignore: bool,
    pub glob: bool,
    pub no_progress: bool,
    pub no_perms: bool,
    pub no_timestamps: bool,
    pub ownership: bool,
    pub driver: String,
    pub no_target_directory: bool,
    pub target_directory: Option<PathBuf>,
    pub fsync: bool,
    pub reflink: String,
    pub backup: String,
}

pub fn parse_size(s: &str) -> Result<u64, String> {
    let s = s.trim();
    if s.is_empty() {
        return Err("could not interpret string as byte size".into());
    }
    let mut num_end = 0;
    for (i, c) in s.char_indices() {
        if c.is_ascii_digit() || c == '.' {
            num_end = i + c.len_utf8();
        } else {
            break;
        }
    }
    if num_end == 0 {
        return Err("could not interpret string as byte size".into());
    }
    let num_str = &s[..num_end];
    let unit_str = s[num_end..].trim();

    let val: f64 = num_str
        .parse()
        .map_err(|_| "could not interpret string as byte size".to_string())?;

    let mult: u64 = match unit_str.to_ascii_lowercase().as_str() {
        "" | "b" => 1,
        "k" | "kb" | "kib" => 1024,
        "m" | "mb" | "mib" => 1024 * 1024,
        "g" | "gb" | "gib" => 1024 * 1024 * 1024,
        "t" | "tb" | "tib" => 1024 * 1024 * 1024 * 1024,
        "p" | "pb" | "pib" => 1024 * 1024 * 1024 * 1024 * 1024,
        _ => return Err("could not interpret string as byte size".to_string()),
    };

    Ok((val * mult as f64) as u64)
}

pub fn build_cli() -> Command {
    Command::new("xcp")
        .version("0.24.3")
        .about("A (partial) clone of the Unix `cp` command with progress and pluggable drivers.")
        .arg(
            Arg::new("paths")
                .value_name("PATHS")
                .num_args(0..)
                .value_parser(ValueParser::os_string())
                .help("Path list.")
                .long_help("Path list.\n\nSource and destination files, or multiple source(s) to a directory."),
        )
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(ArgAction::Count)
                .help("Verbosity.")
                .long_help("Verbosity.\n\nCan be specified multiple times to increase logging."),
        )
        .arg(
            Arg::new("recursive")
                .short('r')
                .long("recursive")
                .action(ArgAction::SetTrue)
                .help("Copy directories recursively"),
        )
        .arg(
            Arg::new("dereference")
                .short('L')
                .long("dereference")
                .action(ArgAction::SetTrue)
                .help("Dereference symlinks in source")
                .long_help("Dereference symlinks in source\n\nFollow symlinks, possibly recursively, when copying source files."),
        )
        .arg(
            Arg::new("workers")
                .short('w')
                .long("workers")
                .value_name("WORKERS")
                .default_value("4")
                .value_parser(ValueParser::from(|s: &str| -> Result<usize, String> {
                    let w: isize = s.parse().map_err(|e| format!("{}", e))?;
                    if w <= 0 {
                        Ok(std::thread::available_parallelism().map(|n| n.get()).unwrap_or(4))
                    } else {
                        Ok(w as usize)
                    }
                }))
                .help("Number of parallel workers.")
                .long_help("Number of parallel workers.\n\nDefault is 4; if the value is negative or 0 it uses the number of logical CPUs."),
        )
        .arg(
            Arg::new("block_size")
                .long("block-size")
                .value_name("BLOCK_SIZE")
                .default_value("1MB")
                .value_parser(ValueParser::from(|s: &str| -> Result<u64, String> {
                    parse_size(s)
                }))
                .help("Block size for operations.")
                .long_help("Block size for operations.\n\nAccepts standard size modifiers like \"M\" and \"GB\". Actual usage internally depends on the driver."),
        )
        .arg(
            Arg::new("no_clobber")
                .short('n')
                .long("no-clobber")
                .action(ArgAction::SetTrue)
                .help("Do not overwrite an existing file"),
        )
        .arg(
            Arg::new("force")
                .short('f')
                .long("force")
                .action(ArgAction::SetTrue)
                .help("Force (compatability only)")
                .long_help("Force (compatability only)\n\nOverwrite files; this is the default behaviour, this flag is for compatibility with `cp` only. See `--no-clobber` for the inverse flag. Using this in conjunction with `--no-clobber` will cause an error."),
        )
        .arg(
            Arg::new("gitignore")
                .long("gitignore")
                .action(ArgAction::SetTrue)
                .help("Use .gitignore if present.")
                .long_help("Use .gitignore if present.\n\nNOTE: This is fairly basic at the moment, and only honours a .gitignore in the directory root for directory copies; global or sub-directory ignores are skipped."),
        )
        .arg(
            Arg::new("glob")
                .short('g')
                .long("glob")
                .action(ArgAction::SetTrue)
                .help("Expand file patterns.")
                .long_help("Expand file patterns.\n\nGlob (expand) filename patterns natively (note; the shell may still do its own expansion first)"),
        )
        .arg(
            Arg::new("no_progress")
                .long("no-progress")
                .action(ArgAction::SetTrue)
                .help("Disable progress bar"),
        )
        .arg(
            Arg::new("no_perms")
                .long("no-perms")
                .action(ArgAction::SetTrue)
                .help("Do not copy the file permissions"),
        )
        .arg(
            Arg::new("no_timestamps")
                .long("no-timestamps")
                .action(ArgAction::SetTrue)
                .help("Do not copy the file timestamps"),
        )
        .arg(
            Arg::new("ownership")
                .short('o')
                .long("ownership")
                .action(ArgAction::SetTrue)
                .help("Copy ownership.")
                .long_help("Copy ownership.\n\nWhether to copy ownship (user/group).  This option requires root permissions or appropriate capabilities; if the attempt to copy ownership fails a warning is issued but the operation continues."),
        )
        .arg(
            Arg::new("driver")
                .long("driver")
                .value_name("DRIVER")
                .default_value("parfile")
                .value_parser(ValueParser::from(|s: &str| -> Result<String, String> {
                    match s {
                        "parfile" | "parblock" => Ok(s.to_string()),
                        _ => Err(format!("Unknown driver: {}", s)),
                    }
                }))
                .help("Driver to use, defaults to 'file-parallel'.")
                .long_help("Driver to use, defaults to 'file-parallel'.\n\nCurrently there are 2; the default \"parfile\", which parallelises copies across workers at the file level, and an experimental \"parblock\" driver, which parellelises at the block level. See also '--block-size'."),
        )
        .arg(
            Arg::new("no_target_directory")
                .short('T')
                .long("no-target-directory")
                .action(ArgAction::SetTrue)
                .help("Target should not be a directory.")
                .long_help("Target should not be a directory.\n\nAnalogous to cp's no-target-directory. Expected behavior is that when copying a directory to another directory, instead of creating a sub-folder in target, overwrite target."),
        )
        .arg(
            Arg::new("target_directory")
                .long("target-directory")
                .value_name("TARGET_DIRECTORY")
                .value_parser(ValueParser::os_string())
                .help("Copy into a subdirectory of the target"),
        )
        .arg(
            Arg::new("fsync")
                .long("fsync")
                .action(ArgAction::SetTrue)
                .help("Sync each file to disk after writing"),
        )
        .arg(
            Arg::new("reflink")
                .long("reflink")
                .value_name("REFLINK")
                .default_value("auto")
                .value_parser(ValueParser::from(|s: &str| -> Result<String, String> {
                    let lower = s.to_ascii_lowercase();
                    match lower.as_str() {
                        "auto" | "always" | "never" => Ok(lower),
                        _ => Err(format!("Invalid arguments: Unexpected value for 'reflink': {}", s)),
                    }
                }))
                .help("Reflink options.")
                .long_help("Reflink options.\n\nWhether and how to use reflinks. 'auto' (the default) will attempt to reflink and fallback to a copy if it is not possible, 'always' will return an error if it cannot reflink, and 'never' will always perform a full data copy.\n\nNote: when using Linux accelerated copy operations (the default when available) the kernel may choose to reflink rather than perform a fully copy regardless of this setting."),
        )
        .arg(
            Arg::new("backup")
                .long("backup")
                .value_name("BACKUP")
                .default_value("none")
                .value_parser(ValueParser::from(|s: &str| -> Result<String, String> {
                    let lower = s.to_ascii_lowercase();
                    match lower.as_str() {
                        "none" | "off" | "numbered" | "auto" => Ok(lower),
                        _ => Err(format!("Invalid arguments: Unexpected value for 'backup': {}", s)),
                    }
                }))
                .help("Backup options")
                .long_help("Backup options\n\nWhether to create backups of overwritten files. Current options are 'none'/'off', or 'numbered', or 'auto'. Numbered backups follow the semantics of `cp` numbered backups (e.g. `file.txt.~123~`). 'auto' will only create a numbered backup if a previous backups exists. Default is 'none'."),
        )
}

pub fn parse_opts() -> Opts {
    let matches = build_cli().get_matches();

    let paths: Vec<PathBuf> = matches
        .get_many::<std::ffi::OsString>("paths")
        .unwrap_or_default()
        .map(PathBuf::from)
        .collect();

    let verbose = matches.get_count("verbose");
    let recursive = matches.get_flag("recursive");
    let dereference = matches.get_flag("dereference");
    let workers = *matches.get_one::<usize>("workers").unwrap_or(&4);
    let block_size = *matches.get_one::<u64>("block_size").unwrap_or(&(1024 * 1024));
    let no_clobber = matches.get_flag("no_clobber");
    let force = matches.get_flag("force");
    let gitignore = matches.get_flag("gitignore");
    let glob = matches.get_flag("glob");
    let no_progress = matches.get_flag("no_progress");
    let no_perms = matches.get_flag("no_perms");
    let no_timestamps = matches.get_flag("no_timestamps");
    let ownership = matches.get_flag("ownership");
    let driver = matches.get_one::<String>("driver").unwrap().clone();
    let no_target_directory = matches.get_flag("no_target_directory");
    let target_directory = matches
        .get_one::<std::ffi::OsString>("target_directory")
        .map(PathBuf::from);
    let fsync = matches.get_flag("fsync");
    let reflink = matches.get_one::<String>("reflink").unwrap().clone();
    let backup = matches.get_one::<String>("backup").unwrap().clone();

    Opts {
        paths,
        verbose,
        recursive,
        dereference,
        workers,
        block_size,
        no_clobber,
        force,
        gitignore,
        glob,
        no_progress,
        no_perms,
        no_timestamps,
        ownership,
        driver,
        no_target_directory,
        target_directory,
        fsync,
        reflink,
        backup,
    }
}
EOF"}

