use is_terminal_polyfill::IsTerminal;
use std::io::{stdout, Write};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Instant;

pub struct ProgressBar {
    total_bytes: AtomicU64,
    copied_bytes: AtomicU64,
    start_time: Instant,
    enabled: bool,
    finished: AtomicBool,
}

impl ProgressBar {
    pub fn new(total_bytes: u64, enabled: bool) -> Arc<Self> {
        let is_tty = std::io::stdout().is_terminal();
        let show = enabled && is_tty;
        Arc::new(Self {
            total_bytes: AtomicU64::new(total_bytes),
            copied_bytes: AtomicU64::new(0),
            start_time: Instant::now(),
            enabled: show,
            finished: AtomicBool::new(false),
        })
    }

    pub fn add_bytes(&self, bytes: u64) {
        let current = self.copied_bytes.fetch_add(bytes, Ordering::Relaxed) + bytes;
        if self.enabled {
            self.render(current);
        }
    }

    pub fn set_total(&self, bytes: u64) {
        self.total_bytes.store(bytes, Ordering::Relaxed);
    }

    pub fn finish(&self) {
        if self.finished.swap(true, Ordering::Relaxed) {
            return;
        }
        if self.enabled {
            let total = self.total_bytes.load(Ordering::Relaxed);
            self.copied_bytes.store(total, Ordering::Relaxed);
            self.render(total);
            let _ = stdout().flush();
        }
    }

    fn render(&self, current: u64) {
        let total = self.total_bytes.load(Ordering::Relaxed);
        let pct = if total > 0 {
            ((current as f64 / total as f64) * 100.0).min(100.0)
        } else {
            0.0
        };

        let fill_len = ((pct * 8.0) / 100.0) as usize;
        let fill_len = fill_len.min(8);
        let bar_fill = "#".repeat(fill_len);
        let bar_empty = "-".repeat(8 - fill_len);
        let bar_str = format!("[{}{}]", bar_fill, bar_empty);

        let cur_str = format_bytes(current);
        let tot_str = format_bytes(total);

        let elapsed = self.start_time.elapsed().as_secs_f64();
        let speed = if elapsed > 0.0 {
            current as f64 / elapsed
        } else {
            0.0
        };
        let speed_str = format!("{}/s", format_bytes(speed as u64));

        let rem_secs = if speed > 0.0 && total > current {
            ((total - current) as f64 / speed) as u64
        } else {
            0
        };
        let h = rem_secs / 3600;
        let m = (rem_secs % 3600) / 60;
        let s = rem_secs % 60;
        let eta_str = format!("{:02}:{:02}:{:02} remaining", h, m, s);

        print!(
            "\r\x1b[2K{} {:>10} / {:<10} | {:>3.0}% | {:>12} | {}",
            bar_str, cur_str, tot_str, pct, speed_str, eta_str
        );
        let _ = stdout().flush();
    }
}

fn format_bytes(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.2} KiB", bytes as f64 / 1024.0)
    } else if bytes < 1024 * 1024 * 1024 {
        format!("{:.2} MiB", bytes as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.2} GiB", bytes as f64 / (1024.0 * 1024 * 1024.0))
    }
}
EOF"}

