        let rem_secs = if speed > 0.0 && total > current {
            ((total - current) as f64 / speed) as u64
        } else {
            0
        };
        let h = rem_secs / 3600;
        let m = (rem_secs % 3600) / 60;
        let s = rem_secs % 60;
        let eta_str = format!("{:02}:{:02}:{:02} remaining", h, m, s);

        print!(
            "\r\x1b[2K{} {:>10} / {:<10} | {:>3.0}% | {:>12} | {}",
            bar_str, cur_str, tot_str, pct, speed_str, eta_str
        );
        let _ = stdout().flush();
    }
}

fn format_bytes(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.2} KiB", bytes as f64 / 1024.0)
    } else if bytes < 1024 * 1024 * 1024 {
        format!("{:.2} MiB", bytes as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.2} GiB", bytes as f64 / (1024.0 * 1024 * 1024.0))
    }
}
