{"command":"cat << 'EOF' > src/drivers/parfile.rs
use crate::cli::Opts;
use crate::drivers::{CopyOp, Driver};
use crate::errors::XcpError;
use crate::fs::*;
use crate::progress::ProgressBar;
use crossbeam_channel::unbounded;
use std::fs::File;
use std::io::{Read, Write};
use std::os::unix::io::AsRawFd;
use std::path::Path;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;

pub struct ParfileDriver;

const FICLONE: u64 = 0x40049409;

impl Driver for ParfileDriver {
    fn copy_all(
        &self,
        ops: Vec<CopyOp>,
        opts: &Opts,
        progress: Option<&Arc<ProgressBar>>,
    ) -> Result<(), XcpError> {
        let (sender, receiver) = unbounded::<CopyOp>();
        for op in ops {
            let _ = sender.send(op);
        }
        drop(sender);

        let num_workers = opts.workers;
        let opts = Arc::new(opts.clone());
        let progress = progress.cloned();
        let has_error = Arc::new(AtomicBool::new(false));
        let error_msg = Arc::new(std::sync::Mutex::new(None));

        let mut handles = Vec::new();

        for _ in 0..num_workers {
            let rx = receiver.clone();
            let opts = opts.clone();
            let progress = progress.clone();
            let has_error = has_error.clone();
            let error_msg = error_msg.clone();

            let handle = thread::spawn(move || {
                let tid = thread::current().id();
                log::debug!("({:?}) libxcp::drivers::parfile: Starting copy worker {:?}", tid, tid);

                while let Ok(op) = rx.recv() {
                    if has_error.load(Ordering::Relaxed) {
                        break;
                    }
                    match op {
                        CopyOp::CreateDir { dst } => {
                            if let Err(e) = std::fs::create_dir_all(&dst) {
                                log::error!("Error creating target directory: {}", e);
                                has_error.store(true, Ordering::Relaxed);
                                *error_msg.lock().unwrap() = Some(XcpError::CopyError(format!("Error creating target directory: {}", e)));
                                break;
                            }
                        }
                        CopyOp::CopyFile { src, dst } => {
                            log::debug!("({:?}) libxcp::drivers::parfile: Received operation Copy({:?}, {:?})", tid, src, dst);
                            log::info!("Worker[{:?}]: Copy {:?} -> {:?}", tid, src, dst);

                            if let Err(e) = copy_single_file_parfile(&src, &dst, &opts, progress.as_ref()) {
                                log::error!("Error copying: {:?} -> {:?}; aborting.", src, dst);
                                log::error!("Received error: {}", e);
                                has_error.store(true, Ordering::Relaxed);
                                *error_msg.lock().unwrap() = Some(e);
                                break;
                            }
                        }
                    }
                }

                log::debug!("({:?}) libxcp::drivers::parfile: Copy worker {:?} shutting down", tid, tid);
            });

            handles.push(handle);
        }

        for h in handles {
            let _ = h.join();
        }

        if has_error.load(Ordering::Relaxed) {
            let err = error_msg.lock().unwrap().take();
            if let Some(e) = err {
                return Err(e);
            }
        }

        Ok(())
    }
}

pub fn copy_single_file_parfile(
    src: &Path,
    dst: &Path,
    opts: &Opts,
    progress: Option<&Arc<ProgressBar>>,
) -> Result<(), XcpError> {
    if opts.no_clobber && dst.exists() {
        return Err(XcpError::DestinationExists(dst.to_path_buf()));
    }

    handle_backup(dst, &opts.backup)?;

    let meta = std::fs::symlink_metadata(src)?;
    if meta.file_type().is_symlink() && !opts.dereference {
        copy_symlink(src, dst)?;
        if !opts.no_perms {
            let _ = copy_permissions(src, dst, &meta);
        }
        if !opts.no_timestamps {
            let _ = copy_timestamps(src, dst, &meta);
        }
