use std::io::{stdout, IsTerminal, Write};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Instant;

pub struct ProgressBar {
    total_bytes: AtomicU64,
    copied_bytes: AtomicU64,
    start_time: Instant,
    enabled: bool,
    finished: AtomicBool,
}

impl ProgressBar {
    pub fn new(total_bytes: u64, enabled: bool) -> Arc<Self> {
        let is_tty = std::io::stdout().is_terminal();
        let show = enabled && is_tty;
        Arc::new(Self {
            total_bytes: AtomicU64::new(total_bytes),
            copied_bytes: AtomicU64::new(0),
            start_time: Instant::now(),
            enabled: show,
            finished: AtomicBool::new(false),
        })
    }

    pub fn add_bytes(&self, bytes: u64) {
        let current = self.copied_bytes.fetch_add(bytes, Ordering::Relaxed) + bytes;
        if self.enabled {
            self.render(current);
        }
    }

    pub fn finish(&self) {
        if self.finished.swap(true, Ordering::Relaxed) {
            return;
        }
        if self.enabled {
            let total = self.total_bytes.load(Ordering::Relaxed);
            self.copied_bytes.store(total, Ordering::Relaxed);
            self.render(total);
            let _ = stdout().flush();
        }
    }

    fn render(&self, current: u64) {
        let total = self.total_bytes.load(Ordering::Relaxed);
        let pct = if total > 0 {
            ((current as f64 / total as f64) * 100.0).min(100.0)
        } else {
            0.0
        };

        let fill_len = ((pct * 8.0) / 100.0) as usize;
        let fill_len = fill_len.min(8);
        let bar_fill = "#".repeat(fill_len);
        let bar_empty = "-".repeat(8 - fill_len);
        let bar_str = format!("[{}{}]", bar_fill, bar_empty);

