{"command":"cat << 'EOF' > src/fs.rs
use crate::errors::XcpError;
use std::ffi::CString;
use std::fs::{File, Metadata};
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::MetadataExt;
use std::path::Path;

pub fn copy_permissions(_src: &Path, dst: &Path, metadata: &Metadata) -> Result<(), XcpError> {
    log::debug!("(...) libfs::common: Performing permissions copy");
    let perms = metadata.permissions();
    let _ = std::fs::set_permissions(dst, perms);
    Ok(())
}

pub fn copy_timestamps(_src: &Path, dst: &Path, metadata: &Metadata) -> Result<(), XcpError> {
    log::debug!("(...) libfs::common: Performing timestamp copy");
    if let (Ok(atime), Ok(mtime)) = (metadata.accessed(), metadata.modified()) {
        let times = std::fs::FileTimes::new().set_accessed(atime).set_modified(mtime);
        if let Ok(file) = File::options().write(true).open(dst) {
            let _ = file.set_times(times);
        }
    }
    Ok(())
}

pub fn copy_ownership(_src: &Path, dst: &Path, metadata: &Metadata) -> Result<(), XcpError> {
    let uid = metadata.uid();
    let gid = metadata.gid();
    if let Ok(dst_c) = CString::new(dst.as_os_str().as_bytes()) {
        unsafe {
            if libc::chown(dst_c.as_ptr(), uid, gid) != 0 {
                log::warn!("Failed to copy ownership for {:?}", dst);
            }
        }
    }
    Ok(())
}

pub fn copy_xattrs(src: &Path, dst: &Path) -> Result<(), XcpError> {
    log::debug!("(...) libfs::common: Starting xattr copy...");
    let src_c = match CString::new(src.as_os_str().as_bytes()) {
        Ok(c) => c,
        Err(_) => return Ok(()),
    };
    let dst_c = match CString::new(dst.as_os_str().as_bytes()) {
        Ok(c) => c,
        Err(_) => return Ok(()),
    };

    let len = unsafe { libc::llistxattr(src_c.as_ptr(), std::ptr::null_mut(), 0) };
    if len <= 0 {
        return Ok(());
    }

    let mut buf = vec![0u8; len as usize];
    let len = unsafe { libc::llistxattr(src_c.as_ptr(), buf.as_mut_ptr() as *mut libc::c_char, buf.len()) };
    if len <= 0 {
        return Ok(());
    }

    let names = buf[..len as usize]
        .split(|&b| b == 0)
        .filter(|s| !s.is_empty());

    for name in names {
        if let Ok(name_c) = CString::new(name) {
            if let Ok(name_str) = std::str::from_utf8(name) {
                log::debug!("(...) libfs::common: Copy xattr {:?}", name_str);
            }
            let val_len = unsafe {
                libc::lgetxattr(
                    src_c.as_ptr(),
                    name_c.as_ptr(),
                    std::ptr::null_mut(),
                    0,
                )
            };
            if val_len >= 0 {
                let mut val_buf = vec![0u8; val_len as usize];
                let val_len = unsafe {
                    libc::lgetxattr(
                        src_c.as_ptr(),
                        name_c.as_ptr(),
                        val_buf.as_mut_ptr() as *mut libc::c_void,
                        val_buf.len(),
                    )
                };
                if val_len >= 0 {
                    unsafe {
                        libc::lsetxattr(
                            dst_c.as_ptr(),
                            name_c.as_ptr(),
                            val_buf.as_ptr() as *const libc::c_void,
                            val_len as usize,
                            0,
                        );
                    }
                }
            }
        }
    }
    Ok(())
}

pub fn handle_backup(dst: &Path, backup_mode: &str) -> Result<(), XcpError> {
    match backup_mode {
        "none" | "off" => Ok(()),
        "auto" => {
            let mut i = 1;
            let mut has_existing = false;
            while i <= 1000 {
                let p = Path::new(&format!("{}.~{}~", dst.display(), i)).to_path_buf();
                if p.exists() {
                    has_existing = true;
                    break;
                }
                i += 1;
            }
            if !has_existing {
                return Ok(());
            }
            do_numbered_backup(dst)
        }
        "numbered" => do_numbered_backup(dst),
        _ => Ok(()),
    }
}

fn do_numbered_backup(dst: &Path) -> Result<(), XcpError> {
    if !dst.exists() {
        return Ok(());
    }
    let mut i = 1;
    loop {
        let backup_path = Path::new(&format!("{}.~{}~", dst.display(), i)).to_path_buf();
        if !backup_path.exists() {
            std::fs::rename(dst, &backup_path)?;
            break;
        }
        i += 1;
    }
    Ok(())
}

pub fn copy_symlink(src: &Path, dst: &Path) -> Result<(), XcpError> {
    let target = std::fs::read_link(src)?;
    if dst.exists() || std::fs::symlink_metadata(dst).is_ok() {
        let _ = std::fs::remove_file(dst);
    }
    std::os::unix::fs::symlink(target, dst)?;
    Ok(())
}

pub fn copy_special_file(_src: &Path, dst: &Path, metadata: &Metadata) -> Result<(), XcpError> {
    let mode = metadata.mode();
    let rdev = metadata.rdev();
    if dst.exists() || std::fs::symlink_metadata(dst).is_ok() {
        let _ = std::fs::remove_file(dst);
    }
    let dst_c = CString::new(dst.as_os_str().as_bytes())
        .map_err(|e| XcpError::CopyError(e.to_string()))?;
    let res = unsafe { libc::mknod(dst_c.as_ptr(), mode, rdev) };
    if res != 0 {
        return Err(XcpError::CopyError(std::io::Error::last_os_error().to_string()));
    }
    Ok(())
}
EOF"}

