        }
        let meta = std::fs::symlink_metadata(src)?;
        if meta.is_dir() && !opts.recursive {
            return Err(XcpError::InvalidSource(
                "Source is directory and --recursive not specified.".into(),
            ));
        }
    }

    // Check same source and destination or directory into itself
    let dest_exists = destination.exists();
    let dest_is_dir = destination.is_dir();

    let dest_canon = if dest_exists {
        std::fs::canonicalize(&destination).ok()
    } else {
        destination.parent().and_then(|p| std::fs::canonicalize(p).ok().map(|cp| cp.join(destination.file_name().unwrap())))
    };

