        if let Ok(src_canon) = std::fs::canonicalize(src) {
            if let Some(dc) = &dest_canon {
                if src_canon == *dc || dc.starts_with(&src_canon) {
                    return Err(XcpError::InvalidSource(
                        "Cannot copy a directory into itself".into(),
                    ));
                }
            }
        }
    }

    if sources.len() > 1 && !dest_is_dir {
        return Err(XcpError::InvalidDestination(
            "Multiple sources and destination is not a directory.".into(),
        ));
    }

