        let meta = std::fs::symlink_metadata(&sources[0])?;
        if meta.is_dir() && dest_exists && !dest_is_dir {
            return Err(XcpError::InvalidDestination(
                "Cannot copy a directory to a file.".into(),
            ));
        }
    }

    let mut ops = Vec::new();
    let mut total_bytes: u64 = 0;

    for src in &sources {
        let meta = std::fs::symlink_metadata(src)?;
        if meta.is_dir() {
            let target_base = if dest_is_dir && !opts.no_target_directory {
                destination.join(src.file_name().unwrap_or_default())
            } else {
                destination.clone()
            };

