                let entry_path = entry.path();
                log::debug!("(...) libxcp::operations: Got tree entry Ok(DirEntry({:?}))", entry_path);

                if let Some(ref matcher) = gitignore_matcher {
                    if matcher.matched(entry_path, entry.file_type().is_dir()).is_ignore() {
                        continue;
                    }
                }

                if entry_path == src {
                    continue;
                }

                let rel = entry_path.strip_prefix(src).unwrap();
                let dst_entry = target_base.join(rel);

                if entry.file_type().is_dir() {
                    log::debug!("(...) libxcp::operations: Creating target directory {:?}", dst_entry);
                    ops.push(CopyOp::CreateDir { dst: dst_entry });
                } else {
                    log::debug!("(...) libxcp::operations: Send copy operation {:?} to {:?}", entry_path, dst_entry);
                    if let Ok(m) = entry.metadata() {
                        total_bytes += m.len();
                    }
                    ops.push(CopyOp::CopyFile {
                        src: entry_path.to_path_buf(),
                        dst: dst_entry,
                    });
                }
            }
            log::debug!("(...) libxcp::operations: Walk-worker finished: ThreadId(3)");
        } else {
            let target_file = if dest_is_dir && !opts.no_target_directory {
                destination.join(src.file_name().unwrap_or_default())
            } else {
                destination.clone()
            };

            log::info!("Copying source {:?} to {:?}", src, target_file);
            total_bytes += meta.len();
            ops.push(CopyOp::CopyFile {
                src: src.clone(),
                dst: target_file,
            });
        }
    }

    let progress = if !opts.no_progress {
        Some(ProgressBar::new(total_bytes, true))
    } else {
        None
    };

    let driver_result = match opts.driver.as_str() {
        "parblock" => {
            let driver = ParblockDriver;
            driver.copy_all(ops, opts, progress.as_ref())
        }
        _ => {
            let driver = ParfileDriver;
            driver.copy_all(ops, opts, progress.as_ref())
        }
    };

    if let Some(ref pb) = progress {
        pb.finish();
    }

    if driver_result.is_ok() {
        log::info!("Copy complete");
    }

    driver_result
}
EOF"}

